var A = function (i) {
    return document.getElementById(i);
  },
  miss = [];
function setL(id, href, t, txt) {
  var a = A(id);
  if (!href) {
    a.textContent = t + ": not added yet";
    a.removeAttribute("href");
    miss.push(t);
    return;
  }
  a.textContent = txt;
  a.href = href;
  if (/^http/.test(href)) {
    a.target = "_blank";
    a.rel = "noopener";
  }
}
setL("cEmail", EMAIL && "mailto:" + EMAIL, "Email", EMAIL);
setL("cPhone", PHONE && "tel:" + PHONE.replace(/\s/g, ""), "Phone", PHONE);
